import numpy as np
mods=list(weights)
print("Overall pairwise weight distance/cos (all weight matrices):")
for i,m1 in enumerate(mods):
    for m2 in mods[i+1:]:
        xs=[];ys=[]
        for n in weights[m1]:
            if n.endswith('weight'):
                xs.append(weights[m1][n].ravel()); ys.append(weights[m2][n].ravel())
        x=np.concatenate(xs); y=np.concatenate(ys)
        rel=np.linalg.norm(x-y)/np.sqrt((np.linalg.norm(x)**2+np.linalg.norm(y)**2)/2)
        cos=np.dot(x,y)/(np.linalg.norm(x)*np.linalg.norm(y))
        print(m1,m2,"rel",round(float(rel),6),"cos",round(float(cos),7),"nr",round(float(np.linalg.norm(x)/np.linalg.norm(y)),4))

print("\nPer block, per type relative change vs each other:")
types=['attn.in_proj_weight','attn.out_proj.weight','mlp.fc1.weight','mlp.fc2.weight']
for b in [4,5,6,7]:
    print("---- block",b)
    for t in types:
        for i,m1 in enumerate(mods):
            for m2 in mods[i+1:]:
                x=weights[m1][f'block{b}.{t}']; y=weights[m2][f'block{b}.{t}']
                rel=np.linalg.norm(x-y)/np.sqrt((np.linalg.norm(x)**2+np.linalg.norm(y)**2)/2)
                cos=np.dot(x.ravel(),y.ravel())/(np.linalg.norm(x)*np.linalg.norm(y))
                print(f"  {t:22s} {m1}{m2} rel={rel:.4f} cos={cos:.5f}")
    print()

print("Norms by type (A B C order):")
for typ in ['ln_1.weight','ln_1.bias','attn.in_proj_weight','attn.in_proj_bias','attn.out_proj.weight','attn.out_proj.bias','ln_2.weight','ln_2.bias','mlp.fc1.weight','mlp.fc1.bias','mlp.fc2.weight','mlp.fc2.bias']:
    print(typ)
    for b in [4,5,6,7]:
        ss=[float(np.linalg.norm(weights[m][f'block{b}.{typ}'])) for m in mods]
        print(" ",b," ".join(f"{v:.4f}" for v in ss))
